import React, { useEffect, useRef } from 'react';
import { xmlUtils } from '@maxgraph/core';
import { after } from 'lodash';

const LogicElementManager = ({ onGenerateCode }) => {
  const lastXmlContent = useRef('');
  const checkInterval = useRef(null);

  const fetchAndGenerate = async () => {
    try {
      const response = await fetch('http://localhost:5000/graph.xml?t=' + Date.now());
      const xmlText = await response.text();
      
      if (xmlText === lastXmlContent.current) return;

      lastXmlContent.current = xmlText;
      const xmlDoc = xmlUtils.parseXml(xmlText);
      const cells = Array.from(xmlDoc.getElementsByTagName('Cell'));

      const elementsById = {};
      const parentMap = {};
      const inputs = [];
      const outputs = [];
      const edges = [];

      for (const cell of cells) {
        const id = cell.getAttribute('id');
        const value = cell.getAttribute('value')?.trim();
        const vertex = cell.getAttribute('vertex');
        const edge = cell.getAttribute('edge');
        const parent = cell.getAttribute('parent');
        const source = cell.getAttribute('source');
        const target = cell.getAttribute('target');
        const shapeObj = cell.querySelector('Object[as="style"]');
        const shape = shapeObj?.getAttribute('shape') || '';
        const rotation = shapeObj?.getAttribute('rotation') || null;

        elementsById[id] = {
          id,
          value,
          vertex,
          edge,
          shape,
          rotation,
          parent,
          source,
          target,
          children: [],
        };

        if (parent) {
          if (!parentMap[parent]) parentMap[parent] = [];
          parentMap[parent].push(id);
        }

        if (edge === '1') {
          let resolvedTarget = target;
        
        // Функция: если target ссылается на другой edge, идём по цепочке target → target → ...
        // В конце берём source у последнего edge в цепочке

        const resolveEdgeTarget = (edgeId) => {
          let current = edgeId;
          let lastEdgeId = null;
        
          console.log("Начальный edgeId:", edgeId); // Печать стартового значения
        
          while (elementsById[current]?.edge === '1') {
            console.log("Внутри цикла:", current, elementsById[current]); // Лог для отслеживания current
            lastEdgeId = current;
            current = elementsById[current].target;
          }
        
          if (lastEdgeId) {
            console.log("lastEdgeId после цикла:", lastEdgeId, elementsById[lastEdgeId]); // Проверка после цикла
          }
        
          // проверка на существование lastEdgeId и его source
          if (lastEdgeId && elementsById[lastEdgeId]) {
            console.log("последний, сурс", elementsById[lastEdgeId].source);
            return elementsById[lastEdgeId].source || '';
          }
        
          return current || '';
        };
        
        
          // Если target пустой, пробуем найти fallback из ребра с id=""
          if (!resolvedTarget || resolvedTarget === '') {
            const emptyIdEdges = Array.from(xmlDoc.getElementsByTagName('Cell')).filter(
              el => el.getAttribute('id') === '' && el.getAttribute('edge') === '1'
            );
        
            if (emptyIdEdges.length > 0) {
              const fallbackSource = emptyIdEdges[0].getAttribute('source');
              console.log(`Ребро ${id} использует source=${fallbackSource} от ребра с id=""`);
        
              if (fallbackSource && elementsById[fallbackSource]) {
                let parentOfSource = elementsById[fallbackSource].parent;
        
                // Если это подпись — ищем родителя
                if (!parentOfSource && elementsById[fallbackSource].vertex === '0') {
                  parentOfSource = Object.values(elementsById).find(el =>
                    el.children?.some(child => child.id === fallbackSource)
                  )?.id;
                }
        
                const finalTarget = resolveEdgeTarget(source);
        
                if (parentOfSource && elementsById[parentOfSource]) {
                  // Меняем местами source и target
                  edges.push({ id, source: fallbackSource, target: finalTarget });
                } else {
                  edges.push({ id, source: fallbackSource, target: finalTarget });
                  console.warn(`Не найден родитель для fallbackSource=${fallbackSource}, используем его напрямую`);
                }
              } else {
                console.warn(`Не найден fallbackSource ${fallbackSource} для edge ${id}`);
                continue;
              }
            } else {
              console.warn(`Не найдено ребро с id="" для edge ${id}`);
              continue;
            }
          } else {
            // Проверяем, ссылается ли resolvedTarget на другой edge
            if (elementsById[resolvedTarget]?.edge === '1') {
              const finalTarget = resolveEdgeTarget(resolvedTarget);
              // Меняем местами
              edges.push({ id, source: finalTarget, target: source });
            } else {
              // Обычное добавление
              edges.push({ id, source, target: resolvedTarget });
            }
          }
          console.log(edges);
        }
        
        
        
      }

      for (const [parentId, childIds] of Object.entries(parentMap)) {
        elementsById[parentId].children = childIds.map(id => elementsById[id]);
      }

      for (const el of Object.values(elementsById)) {
        const shape = el.shape;
        const children = el.children || [];

        if (shape === 'customTriangle' && !el.rotation) {
          const label = children[0]?.value;
          if (label) inputs.push(label);
        }

        if (shape === 'customTriangle' && el.rotation === '180') {
          const label = children[0]?.value;
          if (label) outputs.push(label);
        }
      }

      const allPorts = [
        ...inputs.map(i => ({ name: i, dir: 'in' })),
        ...outputs.map(o => ({ name: o, dir: 'out' }))
      ];

      const portLines = allPorts.map(({ name, dir }, index) => {
        const isLast = index === allPorts.length - 1;
        return `    ${name} : ${dir} std_logic${isLast ? '' : ';'}`;
      });

      const logicLines = [];
      const signalLines = [];
      const elementNames = {};
      const inputsByTarget = {};

      const getParentElement = (elementId) => {
        const element = elementsById[elementId];
        if (!element || !element.parent) return null;
        return elementsById[element.parent];
      };

      // Назначение имён
      for (const el of Object.values(elementsById)) {
        const shape = el.shape;
        const children = el.children || [];
        const label = children[0]?.value || 'unnamed';

        if (shape === 'shape3') {
          elementNames[el.id] = `and_${el.id}`;
        } else if (shape === 'shape4') {
          elementNames[el.id] = `or_${el.id}`;
        } else if (shape === 'shape2') {
          elementNames[el.id] = `not_${el.id}`;
        } else if (shape === 'customTriangle') {
          elementNames[el.id] = label;
        }
      }

      // Сбор входов
      for (const edge of edges) {
        let resolvedTarget = edge.target;

        // Если target пустой, ищем связанное ребро с id=""
        if (!resolvedTarget || resolvedTarget === '') {
          // Ищем ВСЕ ребра с id="", у которых source совпадает с source текущего ребра
          const emptyIdEdges = Object.values(elementsById).filter(
            el => el.id === '' && el.edge === '1'
          );
        
          // Берем первый подходящий вариант (или можно добавить дополнительную проверку)
          if (emptyIdEdges.length > 0) {
            resolvedTarget = emptyIdEdges[0].target;
            console.log(`Ребро ${edge.id} использует target=${resolvedTarget} от ребра с id=""`);
          } else {
            console.warn(`Не найдено ребро с id="" для edge ${edge.id}`);
            continue; // Пропускаем это ребро
          }
        }

        const sourceParent = getParentElement(edge.source);
        const targetParent = getParentElement(resolvedTarget);
        
        if (sourceParent && targetParent) {
          const targetId = targetParent.id;
          const sourceName = elementNames[sourceParent.id];
          
          if (!inputsByTarget[targetId]) inputsByTarget[targetId] = [];
          if (!inputsByTarget[targetId].includes(sourceName)) {
            inputsByTarget[targetId].push(sourceName);
          }
        }
      }

      // Объявляем сигналы для логических элементов
      for (const [id, name] of Object.entries(elementNames)) {
        if (name.startsWith('and_') || name.startsWith('or_') || name.startsWith('not_')) {
          signalLines.push(`  signal ${name} : std_logic;`);
        }
      }

      // Генерация логики
      for (const [targetId, inputNames] of Object.entries(inputsByTarget)) {
        const targetEl = elementsById[targetId];
        const shape = targetEl.shape;
        const targetName = elementNames[targetId];

        if (shape === 'shape3') {
          logicLines.push(`  ${targetName} <= ${inputNames.join(' and ')};`);
        } else if (shape === 'shape4') {
          logicLines.push(`  ${targetName} <= ${inputNames.join(' or ')};`);
        } else if (shape === 'shape2') {
          logicLines.push(`  ${targetName} <= not ${inputNames[0]};`);
        } else if (shape === 'customTriangle' && targetEl.rotation === '180') {
          logicLines.push(`  ${targetName} <= ${inputNames[0]};`);
        }
      }

      const generateTestbench = (inputs, outputs) => {
        const inputSignals = inputs.map(i => `  signal ${i} : std_logic := '0';`);
        const outputSignals = outputs.map(o => `  signal ${o} : std_logic;`);
        const signalLines = [...inputSignals, ...outputSignals];
      
        const allPorts = [
          ...inputs.map(i => ({ name: i, dir: 'in' })),
          ...outputs.map(o => ({ name: o, dir: 'out' }))
        ];
      
        const componentPorts = allPorts.map((port, idx) => {
          const isLast = idx === allPorts.length - 1;
          return `      ${port.name} : ${port.dir} std_logic${isLast ? '' : ';'}`;
        }).join('\n');
      
        const portMapLines = [
          ...inputs.map(i => `      ${i} => ${i},`),
          ...outputs.map((o, idx) => {
            const isLast = idx === outputs.length - 1;
            return `      ${o} => ${o}${isLast ? '' : ','}`;
          })
        ];
      
        return [
          'library ieee;',
          'use ieee.std_logic_1164.all;',
          'use ieee.numeric_std.all;\n',
          'entity tb_adder  is',
          'end tb_adder;\n',
          'architecture testbench of tb_adder is',
          '',
          ...signalLines,
          '',
          '  component circuit',
          '    port (',
          componentPorts,
          '    );',
          '  end component;',
          '',
          'begin',
          '',
          '  uut: circuit',
          '    port map (',
          ...portMapLines,
          '    );',
          '',
          '  stim_proc: process',
          '  begin',
          '    wait;',
          '  end process;',
          '',
          'end testbench;'
        ].join('\n');
      };
      

      const vhdl = [
        'library ieee;',
        'use ieee.std_logic_1164.all;',
        'use ieee.numeric_std.all;\n',
        'entity circuit is',
        '  port (',
        ...portLines,
        '  );',
        'end circuit;\n',
        'architecture rtl of circuit is',
        ...signalLines,
        'begin',
        ...logicLines,
        'end rtl;'
      ].join('\n');

      onGenerateCode(vhdl, generateTestbench(inputs, outputs));
    } catch (e) {
      console.error('Ошибка при обработке XML:', e);
    }
  };

  useEffect(() => {
    fetchAndGenerate();
    checkInterval.current = setInterval(fetchAndGenerate, 300);

    return () => {
      if (checkInterval.current) {
        clearInterval(checkInterval.current);
      }
    };
  }, [onGenerateCode]);

  return null;
};

export default LogicElementManager;